import React, { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, CalendarDays, Download, FileJson, FolderPlus, Layers3, Plus, Save, Workflow, Zap } from 'lucide-react';
import { createDefaultWorkspace } from './domain/migration';
import { loadV1, saveV1 } from './domain/storage';
import { forecastWorkspace, type Forecast } from './domain/forecast';
import { validateWorkspace } from './domain/validation';
import { proposeForGate, type Proposal } from './domain/optimization';
import { exportProject, importProjectIntoWorkspace, type ProjectExport } from './domain/import-export';
import { captureBaseline, extendBaseline } from './domain/baseline';
import { decideImpact, deleteProjectPreservingReferences, deleteTaskPreservingReferences, downstreamOf, ordinaryVersionUpdate, projectDeletionImpact, taskDeletionImpact, transferOrdinaryDeliverable } from './domain/actions';
import { proposeResourceAlternatives, type ResourceAlternative } from './domain/resource-alternatives';
import { recordAuditChanges } from './domain/audit';
import { reconcileRiskHistory } from './domain/risk';
import { importLegacyProject } from './domain/legacy-import';
import { isWorkday } from './domain/calendar';
import { makeWorkspaceBackup, parseWorkspaceBackup } from './domain/backup';
import { adoptPlanChanges, planOptions } from './domain/plan';
import { proposeBookingRemedy } from './domain/resource-remedy';
import type { Deliverable, Dependency, PlanChange, Project, Task, WorkspaceV1 } from './domain/model';

type Tab = 'overview' | 'tasks' | 'dependencies' | 'resources' | 'data';
const dateToday = () => new Date().toLocaleDateString('sv-SE');
const id = () => crypto.randomUUID();
const classes = { input: 'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200', button: 'rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700', secondary: 'rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50' };
function remedy(type: string): string | null {
  if (type === 'HARD_DEADLINE') return '条件性补救：确认可提前的成果交付、外部测试资源或最短工期后重新模拟；未经确认不能视为达成。';
  if (type === 'RESOURCE_CONFLICT') return '条件性补救：核实是否可错峰预约或增加设备；当前预约尚未自动变更。';
  return null;
}
export default function V1App() {
  const [workspace, setWorkspace] = useState<WorkspaceV1 | null>(null);
  const [recoveryData, setRecoveryData] = useState<unknown>(null);
  const [loadError, setLoadError] = useState('');
  const [projectId, setProjectId] = useState('');
  const [tab, setTab] = useState<Tab>('overview');
  const [saveStatus, setSaveStatus] = useState('正在读取本地数据…');
  const [error, setError] = useState('');
  const [newProject, setNewProject] = useState('');
  const [newTask, setNewTask] = useState('');
  const [newTaskStage, setNewTaskStage] = useState('');
  const [newStage, setNewStage] = useState('');
  const [newGate, setNewGate] = useState('');
  const [newGateTarget, setNewGateTarget] = useState(dateToday());
  const [newGateTask, setNewGateTask] = useState('');
  const [newGateStage, setNewGateStage] = useState('');
  const [newGateDeadline, setNewGateDeadline] = useState<'soft' | 'hard'>('soft');
  const [dependencyTargetType, setDependencyTargetType] = useState<Dependency['targetType']>('task_start');
  const [newDeliverable, setNewDeliverable] = useState('');
  const [newDeliverableKind, setNewDeliverableKind] = useState<Deliverable['kind']>('required');
  const [deliverableTask, setDeliverableTask] = useState('');
  const [dependencySource, setDependencySource] = useState('');
  const [dependencyTarget, setDependencyTarget] = useState('');
  const [newResource, setNewResource] = useState('');
  const [bookingResource, setBookingResource] = useState('');
  const [bookingTask, setBookingTask] = useState('');
  const [bookingDate, setBookingDate] = useState(dateToday());
  const [bookingDays, setBookingDays] = useState(1);
  const [pendingImport, setPendingImport] = useState<WorkspaceV1 | null>(null);
  const [pendingProjectImport, setPendingProjectImport] = useState<WorkspaceV1 | null>(null);
  const [pendingLegacyImport, setPendingLegacyImport] = useState<WorkspaceV1 | null>(null);
  const [proposal, setProposal] = useState<Proposal | null>(null);
  const [resourceAlternatives, setResourceAlternatives] = useState<ResourceAlternative[]>([]);
  const [remedyProposal, setRemedyProposal] = useState<ResourceAlternative | null>(null);
  const [remedyBooking, setRemedyBooking] = useState('');
  const [remedyResource, setRemedyResource] = useState('');
  const [remedyDate, setRemedyDate] = useState(dateToday());
  const [pendingDeleteProject, setPendingDeleteProject] = useState(false);
  const [versionNotes, setVersionNotes] = useState<Record<string, string>>({});
  const [taskFilter, setTaskFilter] = useState<'all' | Task['status']>('all');
  const [riskOnly, setRiskOnly] = useState(false);
  const [collapsedStages, setCollapsedStages] = useState<string[]>([]);
  const [bookingAnchor, setBookingAnchor] = useState<'fixed_date' | 'task_relative'>('fixed_date');
  const [bookingOffset, setBookingOffset] = useState(0);
  const [occupiedDate, setOccupiedDate] = useState(dateToday());
  const [completionTaskId, setCompletionTaskId] = useState('');
  const [pendingDeleteTaskId, setPendingDeleteTaskId] = useState('');
  const [completionDate, setCompletionDate] = useState(dateToday());
  const [completionReasons, setCompletionReasons] = useState<Record<string, string>>({});

  useEffect(() => {
    loadV1().then(saved => {
      if (saved) {
        if (saved.schemaVersion !== 1) { setRecoveryData(saved); setLoadError('本地数据版本不受支持，尚未覆盖原数据'); return; }
        try {
          const issues = validateWorkspace(saved);
          if (issues.length) { setRecoveryData(saved); setLoadError(`本地数据校验失败：${issues[0]}`); return; }
        } catch { setRecoveryData(saved); setLoadError('本地数据结构无法读取'); return; }
      }
      const value = saved?.schemaVersion === 1 ? saved : createDefaultWorkspace();
      value.baselineSnapshots ||= value.projects.map(captureBaseline);
      value.riskEvents = reconcileRiskHistory(value.riskEvents, forecastWorkspace(value, { today: dateToday() }));
      setWorkspace(value); setProjectId(value.currentProjectId || value.projects[0]?.id || '');
    }).catch(() => { setLoadError('本地存储读取失败，尚未覆盖原数据。请检查浏览器存储权限后刷新。'); });
  }, []);

  useEffect(() => {
    setNewTaskStage(''); setNewGateStage(''); setNewGateTask(''); setDeliverableTask('');
    setDependencySource(''); setDependencyTarget(''); setCompletionTaskId(''); setPendingDeleteTaskId('');
    setProposal(null); setResourceAlternatives([]); setRemedyProposal(null);
  }, [projectId]);

  useEffect(() => {
    if (!workspace) return;
    let active = true;
    setSaveStatus('正在保存…');
    saveV1(workspace).then(() => { if (active) setSaveStatus('已保存到此浏览器'); }).catch(() => { if (active) setSaveStatus('保存失败，请导出备份'); });
    return () => { active = false; };
  }, [workspace]);

  const computed = useMemo(() => {
    if (!workspace) return null;
    try { return forecastWorkspace(workspace, { today: dateToday() }); } catch (cause) { return { error: cause instanceof Error ? cause.message : '排期计算失败' }; }
  }, [workspace]);
  const forecast = computed && 'tasks' in computed ? computed : null;
  const proposalForecast = useMemo(() => {
    if (!workspace || !proposal) return null;
    try { return forecastWorkspace(workspace, { ...planOptions(proposal.changes), today: dateToday() }); } catch { return null; }
  }, [workspace, proposal]);
  const project = workspace?.projects.find(item => item.id === projectId) || workspace?.projects[0];
  const allTasks = workspace?.projects.flatMap(item => item.tasks.map(task => ({ task, project: item }))) || [];
  const allDeliverables = allTasks.flatMap(({ task, project: owner }) => task.deliverables.map(deliverable => ({ deliverable, task, project: owner })));
  const activeRisks = workspace?.riskEvents.filter(event => event.state !== 'resolved') || [];
  const acceptedForecast = useMemo(() => {
    if (!workspace?.planRevisions.length) return null;
    const latest = workspace.planRevisions.at(-1)!;
    try { return forecastWorkspace(workspace, { ...planOptions(latest.changes), today: dateToday() }); } catch { return null; }
  }, [workspace]);

  function change(mutator: (draft: WorkspaceV1) => void): boolean {
    if (!workspace) return false;
    const draft: WorkspaceV1 = structuredClone(workspace);
    try {
      mutator(draft);
      const issues = validateWorkspace(draft);
      if (issues.length) { setError(issues[0]); return false; }
      recordAuditChanges(workspace, draft);
      for (const item of draft.projects) { const prior = workspace.projects.find(project => project.id === item.id); if (prior && JSON.stringify({ ...prior, updatedAt: undefined }) !== JSON.stringify({ ...item, updatedAt: undefined })) item.updatedAt = new Date().toISOString(); }
      const nextForecast = forecastWorkspace(draft, { today: dateToday() });
      extendBaseline(draft, nextForecast);
      draft.riskEvents = reconcileRiskHistory(draft.riskEvents, nextForecast);
      setWorkspace(draft); setProposal(null); setResourceAlternatives([]); setRemedyProposal(null); setError(''); return true;
    } catch (cause) { setError(cause instanceof Error ? cause.message : '操作失败'); return false; }
  }
  function editTask(taskId: string, mutator: (task: Task) => void) { return change(draft => { const task = draft.projects.flatMap(p => p.tasks).find(item => item.id === taskId); if (!task) throw new Error('任务不存在'); mutator(task); }); }
  function editDeliverable(deliverableId: string, mutator: (item: Deliverable) => void) { change(draft => { const item = draft.projects.flatMap(p => p.tasks).flatMap(t => t.deliverables).find(entry => entry.id === deliverableId); if (!item) throw new Error('成果不存在'); mutator(item); }); }
  function addProject(event: React.FormEvent) {
    event.preventDefault(); if (!newProject.trim()) return;
    const nextId = id();
    change(draft => { const next: Project = { id: nextId, name: newProject.trim(), startDate: dateToday(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), priority: 'medium', status: 'active', stages: [{ id: id(), name: 'TR1', order: 0 }], gates: [], tasks: [] }; draft.projects.push(next); draft.currentProjectId = nextId; draft.baselineSnapshots ||= []; draft.baselineSnapshots.push(captureBaseline(next)); });
    setProjectId(nextId); setNewProject('');
  }
  function addTask(event: React.FormEvent) {
    event.preventDefault(); if (!newTask.trim() || !project) return;
    change(draft => {
      const target = draft.projects.find(item => item.id === project.id)!;
      target.tasks.push({ id: id(), stageId: newTaskStage || target.stages[0].id, title: newTask.trim(), status: 'not_started', standardDurationDays: 1, minimumDurationDays: 1, deliverables: [] });
    }); setNewTask('');
  }
  function addStage(event: React.FormEvent) {
    event.preventDefault(); if (!newStage.trim() || !project) return;
    change(draft => { const target = draft.projects.find(item => item.id === project.id)!; target.stages.push({ id: id(), name: newStage.trim(), order: target.stages.length }); });
    setNewStage('');
  }
  function addGate(event: React.FormEvent) {
    event.preventDefault(); if (!newGate.trim() || !project) return;
    change(draft => { const target = draft.projects.find(item => item.id === project.id)!; target.gates.push({ id: id(), name: newGate.trim(), stageId: newGateStage || target.stages[0]?.id, targetDate: newGateTarget, deadlineType: newGateDeadline, requiredTaskIds: newGateTask.startsWith('task:') ? [newGateTask.slice(5)] : [], requiredDeliverableIds: newGateTask.startsWith('deliverable:') ? [newGateTask.slice(12)] : [] }); });
    setNewGate('');
  }
  function addDeliverable(event: React.FormEvent) {
    event.preventDefault(); if (!newDeliverable.trim() || !deliverableTask) return;
    editTask(deliverableTask, task => task.deliverables.push({ id: id(), name: newDeliverable.trim(), kind: newDeliverableKind, standardOffsetDays: 1, earliestOffsetDays: 1, status: 'pending', versionHistory: [] }));
    setNewDeliverable('');
  }
  function setDeliverableStatus(deliverableId: string, nextStatus: Deliverable['status']) {
    editDeliverable(deliverableId, item => {
      if (item.status === nextStatus) return;
      if (nextStatus === 'pending' && item.currentVersionId) throw new Error('已交付成果请先标记失效；历史交付不能改回未交付');
      if (nextStatus === 'cancelled' && item.kind === 'required') throw new Error('必需成果请先明确修改验收类别，再填写取消原因');
      if (nextStatus === 'invalidated') {
        if (item.status !== 'delivered') throw new Error('只有已交付成果才能标记失效');
        const version = item.versionHistory.find(entry => entry.id === item.currentVersionId);
        if (version) version.invalidatedAt = new Date().toISOString();
        item.actualDeliveredDate = undefined;
      }
      if (nextStatus === 'delivered') {
        if (!item.actualDeliveredDate) throw new Error('请先填写本次实际交付日期');
        const previous = item.versionHistory.find(entry => entry.id === item.currentVersionId);
        if (previous?.deliveredAt === item.actualDeliveredDate) throw new Error('重新交付需填写本次新的实际日期');
        item.currentVersionId = id();
        item.versionHistory.push({ id: item.currentVersionId, label: `V${item.versionHistory.length + 1}`, createdAt: new Date().toISOString(), deliveredAt: item.actualDeliveredDate });
      }
      item.status = nextStatus;
    });
  }
  function transferDeliverable(deliverableId: string, targetTaskId: string) {
    if (!targetTaskId) return;
    change(draft => Object.assign(draft, transferOrdinaryDeliverable(draft, deliverableId, targetTaskId)));
  }
  function moveStage(stageId: string, direction: -1 | 1) {
    change(draft => {
      const stages = draft.projects.find(item => item.id === project.id)!.stages.sort((a, b) => a.order - b.order);
      const index = stages.findIndex(item => item.id === stageId);
      const neighbor = stages[index + direction];
      if (!neighbor) return;
      [stages[index].order, neighbor.order] = [neighbor.order, stages[index].order];
    });
  }
  function moveTask(taskId: string, direction: -1 | 1) {
    change(draft => {
      const tasks = draft.projects.find(item => item.id === project.id)!.tasks;
      const index = tasks.findIndex(item => item.id === taskId);
      const peers = tasks.map((item, position) => ({ item, position })).filter(entry => entry.item.stageId === tasks[index].stageId);
      const peerIndex = peers.findIndex(entry => entry.item.id === taskId);
      const neighbor = peers[peerIndex + direction];
      if (neighbor) [tasks[index], tasks[neighbor.position]] = [tasks[neighbor.position], tasks[index]];
    });
  }
  function addDependency(event: React.FormEvent) {
    event.preventDefault(); if (!dependencySource || !dependencyTarget) return;
    const source = allDeliverables.find(item => item.deliverable.id === dependencySource);
    change(draft => { const edgeId = id(); draft.dependencies.push({ id: edgeId, sourceType: 'deliverable', sourceId: dependencySource, targetType: dependencyTargetType, targetId: dependencyTarget, sourceNameSnapshot: source?.deliverable.name, acceptedSourceVersionId: source?.deliverable.currentVersionId }); draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: 'dependency', entityId: edgeId, action: 'create', next: dependencySource + ' → ' + dependencyTarget }); });
  }
  function download(name: string, value: unknown) {
    const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' }));
    const link = document.createElement('a'); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  function commitPlan(changes: PlanChange[], note: string, gateId?: string): boolean {
    if (!workspace) return false;
    try {
      const next = adoptPlanChanges(workspace, changes, note, gateId, dateToday());
      next.riskEvents = reconcileRiskHistory(next.riskEvents, forecastWorkspace(next, { today: dateToday() }));
      setWorkspace(next); setError(''); return true;
    } catch (cause) { setError(cause instanceof Error ? cause.message : '采纳失败'); return false; }
  }
  function adoptProposal() {
    if (!proposal?.feasible) return;
    if (commitPlan(proposal.changes, `GA ${proposal.gateId} 候选 ${proposal.proposedDate}`, proposal.gateId)) setProposal(null);
  }
  function adoptResourceAlternative(candidate: ResourceAlternative) {
    if (candidate.feasible && commitPlan(candidate.changes, `资源 ${candidate.resourceId} 联合错峰`)) setResourceAlternatives([]);
  }
  async function importWorkspace(file: File) {
    try {
      const candidate = parseWorkspaceBackup(JSON.parse(await file.text()));
      setPendingImport(candidate); setError('');
    } catch (cause) { setError(cause instanceof Error ? cause.message : '导入失败'); }
  }
  async function importSingleProject(file: File) {
    if (!workspace) return;
    try {
      const parsed = JSON.parse(await file.text()) as ProjectExport;
      const candidate = importProjectIntoWorkspace(workspace, parsed);
      const issues = validateWorkspace(candidate);
      if (issues.length) throw new Error(issues[0]);
      candidate.baselineSnapshots ||= [];
      if (!candidate.baselineSnapshots.some(item => item.projectId === candidate.projects.at(-1)!.id)) candidate.baselineSnapshots.push(captureBaseline(candidate.projects.at(-1)!));
      extendBaseline(candidate, forecastWorkspace(candidate, { today: dateToday() }));
      setPendingProjectImport(candidate); setError('');
    } catch (cause) { setError(cause instanceof Error ? cause.message : '项目导入失败'); }
  }

  async function importLegacyFile(file: File) {
    if (!workspace) return;
    try {
      const parsed: unknown = JSON.parse(await file.text());
      const candidate = importLegacyProject(workspace, parsed);
      const issues = validateWorkspace(candidate);
      if (issues.length) throw new Error(issues[0]);
      setPendingLegacyImport(candidate); setError('');
    } catch (cause) { setError(cause instanceof Error ? cause.message : '旧版项目转换失败'); }
  }

  if (loadError) return <main className="max-w-xl mx-auto p-8"><h1 className="text-xl font-bold mb-3">无法安全读取工作区</h1><p role="alert" className="text-red-700 mb-4">{loadError}</p>{recoveryData && <button className={classes.button} onClick={() => download('ipd-recovery.json', recoveryData)}>下载原始数据以便修复</button>}</main>;
  if (!workspace) return <main className="p-8">正在读取项目…</main>;
  if (!project) return <main className="max-w-xl mx-auto p-8"><h1 className="text-xl font-bold mb-3">还没有项目</h1>{error && <p role="alert" className="mb-4 rounded border border-red-300 bg-red-50 p-3 text-red-700">{error}</p>}<p className="text-slate-600 mb-4">新建第一个项目，或从备份文件恢复工作区。</p><form onSubmit={addProject} className="flex gap-2"><input className={classes.input} aria-label="新项目名称" value={newProject} onChange={event => setNewProject(event.target.value)} /><button className={classes.button}>新建项目</button></form><label className={`${classes.secondary} inline-block mt-4`}>选择工作区备份<input hidden type="file" accept=".json,application/json" onChange={event => { const file = event.target.files?.[0]; if (file) void importWorkspace(file); event.target.value = ''; }} /></label>{pendingImport && <button className={`${classes.button} mt-4`} onClick={() => { setWorkspace(pendingImport); setProjectId(pendingImport.currentProjectId || pendingImport.projects[0]?.id || ''); setPendingImport(null); }}>确认恢复 {pendingImport.projects.length} 个项目</button>}</main>;
  const gateRows = project.gates.map(gate => ({ gate, predicted: forecast?.gates[gate.id] }));
  const nextGate = [...gateRows].filter(row => !row.gate.actualAchievedDate).sort((a, b) => a.gate.targetDate.localeCompare(b.gate.targetDate))[0];
  const done = project.tasks.filter(task => task.status === 'done').length;
  const deletionImpact = projectDeletionImpact(workspace, project.id);
  const taskToComplete = allTasks.find(entry => entry.task.id === completionTaskId)?.task;
  const taskToDelete = allTasks.find(entry => entry.task.id === pendingDeleteTaskId)?.task;
  const progress = project.tasks.length ? Math.round(done / project.tasks.length * 100) : 0;

  return <div className="min-h-screen bg-[#f5f8fc] text-slate-900">
    <header className="bg-white border-b border-slate-200 sticky top-0 z-40"><div className="max-w-[1500px] mx-auto px-4 sm:px-8 py-4 flex flex-wrap gap-4 items-center">
      <div className="w-12 h-12 bg-blue-600 rounded-xl grid place-items-center text-white shadow-lg shadow-blue-100"><Zap /></div>
      <div><h1 className="text-xl font-bold">项目管理</h1><p className="text-xs text-slate-500">IPD 智能排期工作区</p></div>
      <select aria-label="切换项目" className={`${classes.input} max-w-64 ml-auto`} value={project.id} onChange={event => { const selected = event.target.value; if (change(draft => { draft.currentProjectId = selected; })) setProjectId(selected); }}>{workspace.projects.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select>
      <span role="status" className="text-xs text-slate-500">{saveStatus}</span>
    </div></header>
    <main className="max-w-[1500px] mx-auto p-4 sm:p-8 space-y-6">
      {error && <div role="alert" className="rounded-xl border border-red-300 bg-red-50 p-4 text-red-700">{error}</div>}
      {computed && 'error' in computed && <div role="alert" className="rounded-xl border border-red-300 bg-red-50 p-4 text-red-700">{computed.error}</div>}
      <section className="bg-white border border-slate-200 rounded-2xl p-5 grid md:grid-cols-4 gap-4 items-end">
        <label className="text-xs font-semibold text-slate-500">项目名称<input className={classes.input} value={project.name} onChange={event => change(draft => { draft.projects.find(item => item.id === project.id)!.name = event.target.value; })} /></label>
        <label className="text-xs font-semibold text-slate-500">项目启动 <span className="font-normal">原始 {workspace.baselineSnapshots?.find(item => item.projectId === project.id)?.projectStartDate || "未记录"}</span><input type="date" className={classes.input} value={project.startDate} onChange={event => change(draft => { draft.projects.find(item => item.id === project.id)!.startDate = event.target.value; })} /></label>
        <label className="text-xs font-semibold text-slate-500">项目优先级<select className={classes.input} value={project.priority} onChange={event => change(draft => { draft.projects.find(item => item.id === project.id)!.priority = event.target.value as Project['priority']; })}><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label>
        <label className="text-xs font-semibold text-slate-500">状态<select className={classes.input} value={project.status} onChange={event => change(draft => { draft.projects.find(item => item.id === project.id)!.status = event.target.value as Project['status']; })}><option value="active">进行中</option><option value="archived">已归档</option></select></label>
        <label className="md:col-span-4 text-xs font-semibold text-slate-500">项目说明<textarea className={classes.input} placeholder="项目背景与范围" value={project.description || ''} onChange={event => change(draft => { draft.projects.find(item => item.id === project.id)!.description = event.target.value; })} /></label>
      </section>
      <nav aria-label="工作区页面" className="flex gap-2 overflow-x-auto border-b border-slate-200">{([['overview','总览'],['tasks','任务与成果'],['dependencies','跨项目依赖'],['resources','关键资源'],['data','数据管理']] as [Tab,string][]).map(([key,label]) => <button key={key} className={`whitespace-nowrap px-4 py-3 text-sm font-semibold border-b-2 ${tab === key ? 'border-blue-600 text-blue-700' : 'border-transparent text-slate-500'}`} onClick={() => setTab(key)}>{label}</button>)}</nav>
      {tab === 'overview' && <>
        <form onSubmit={addGate} className="bg-white rounded-2xl border border-slate-200 p-4 flex flex-wrap gap-3 items-end"><label className="text-xs font-semibold text-slate-500">新增 GA<input className={classes.input} value={newGate} onChange={event => setNewGate(event.target.value)} placeholder="例如 TR1 评审" /></label><label className="text-xs font-semibold text-slate-500">目标日期<input type="date" className={classes.input} value={newGateTarget} onChange={event => setNewGateTarget(event.target.value)} /></label><label className="text-xs font-semibold text-slate-500">所属阶段<select className={classes.input} value={newGateStage} onChange={event => setNewGateStage(event.target.value)}><option value="">首个阶段</option>{project.stages.map(stage => <option key={stage.id} value={stage.id}>{stage.name}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">截止类型<select className={classes.input} value={newGateDeadline} onChange={event => setNewGateDeadline(event.target.value as 'soft' | 'hard')}><option value="soft">普通目标</option><option value="hard">硬截止</option></select></label><label className="text-xs font-semibold text-slate-500">完成判据<select className={classes.input} value={newGateTask} onChange={event => setNewGateTask(event.target.value)}><option value="">手动确认</option>{project.tasks.map(task => <option key={task.id} value={`task:${task.id}`}>任务：{task.title}</option>)}{project.tasks.flatMap(task => task.deliverables.map(item => <option key={item.id} value={`deliverable:${item.id}`}>成果：{item.name}</option>))}</select></label><button className={classes.button}>添加 GA</button></form>
        <div className="grid lg:grid-cols-3 gap-5">
          <div className="bg-white rounded-2xl border border-slate-200 p-6"><Layers3 className="text-blue-600 mb-6" /><p className="text-sm text-slate-500">当前进度</p><strong className="text-4xl">{progress}%</strong><p className="text-slate-500 text-sm">{done} / {project.tasks.length} 任务</p></div>
          <div className="bg-white rounded-2xl border border-slate-200 p-6"><CalendarDays className="text-blue-600 mb-6" /><p className="text-sm text-slate-500">下一个 GA</p><strong className="text-2xl">{nextGate?.predicted?.date || '未配置预测依据'}</strong><p className="text-slate-500 text-sm">目标：{nextGate?.gate.targetDate || '未设置'}</p></div>
          <div className="bg-white rounded-2xl border border-orange-200 p-6"><AlertTriangle className="text-orange-600 mb-6" /><p className="text-sm text-slate-500">当前风险</p><strong className="text-4xl">{activeRisks.length}</strong><p className="text-slate-500 text-sm">所有项目合计</p></div>
        </div>
        <section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">阶段 GA</h2><div className="space-y-3">{gateRows.map(({ gate, predicted }) => <div key={gate.id} className="flex flex-wrap gap-3 items-center border-b pb-3 text-sm"><input aria-label={`${gate.name}名称`} className="border rounded px-2 py-1 font-semibold" value={gate.name} onChange={event => change(draft => { draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!.name = event.target.value; })} /><label>目标 <input aria-label={`${gate.name}目标日期`} type="date" className="border rounded px-2 py-1" value={gate.targetDate} onChange={event => change(draft => { draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!.targetDate = event.target.value; })} /></label><span>原始目标 {workspace.baselineSnapshots?.find(item => item.projectId === project.id)?.gateTargets[gate.id] || '未冻结'}</span><span>原始预计 {workspace.baselineSnapshots?.find(item => item.projectId === project.id)?.gatePredictedDates?.[gate.id] || '未记录'}</span><span>标准预计 {predicted?.date || '无法预测'}</span>{acceptedForecast && <span className="text-blue-700">已采纳版预计 {acceptedForecast.gates[gate.id]?.date || '无法预测'}</span>}<label>阶段 <select aria-label={`${gate.name}所属阶段`} className="border rounded px-2 py-1" value={gate.stageId || ""} onChange={event => change(draft => { draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!.stageId = event.target.value || undefined; })}><option value="">未关联</option>{project.stages.map(stage => <option key={stage.id} value={stage.id}>{stage.name}</option>)}</select></label><label>截止类型 <select aria-label={`${gate.name}截止类型`} className="border rounded px-2 py-1" value={gate.deadlineType} onChange={event => change(draft => { draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!.deadlineType = event.target.value as 'soft' | 'hard'; })}><option value="soft">普通目标</option><option value="hard">硬截止</option></select></label><label>实际达成 <input aria-label={`${gate.name}实际达成日期`} type="date" className="border rounded px-2 py-1" value={gate.actualAchievedDate || ''} onChange={event => change(draft => { draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!.actualAchievedDate = event.target.value || undefined; })} /></label><button className={classes.secondary} onClick={() => { try { setProposal(proposeForGate(workspace, gate.id, dateToday())); } catch (cause) { setError(cause instanceof Error ? cause.message : '候选计算失败'); } }}>生成候选</button><button className="text-red-700" onClick={() => { if (!window.confirm(`删除 GA「${gate.name}」？历史风险和审计记录将保留。`)) return; change(draft => { draft.projects.find(item => item.id === project.id)!.gates = draft.projects.find(item => item.id === project.id)!.gates.filter(item => item.id !== gate.id); draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: "gate", entityId: gate.id, action: "delete", previous: gate.name }); }); }}>删除 GA</button><details className="w-full"><summary className="cursor-pointer text-blue-700">完成判据：{gate.requiredTaskIds.length} 项任务、{gate.requiredDeliverableIds.length} 项成果</summary><div className="mt-2 flex flex-wrap gap-3">{project.tasks.map(task => <label key={task.id} className="flex items-center gap-1"><input type="checkbox" checked={gate.requiredTaskIds.includes(task.id)} onChange={event => change(draft => { const target = draft.projects.flatMap(item => item.gates).find(item => item.id === gate.id)!; target.requiredTaskIds = event.target.checked ? [...target.requiredTaskIds, task.id] : target.requiredTaskIds.filter(id => id !== task.id); })} />{task.title}</label>)}{project.tasks.flatMap(task => task.deliverables.map(item => <label key={item.id} className="flex items-center gap-1"><input type="checkbox" checked={gate.requiredDeliverableIds.includes(item.id)} onChange={event => change(draft => { const target = draft.projects.flatMap(project => project.gates).find(entry => entry.id === gate.id)!; target.requiredDeliverableIds = event.target.checked ? [...target.requiredDeliverableIds, item.id] : target.requiredDeliverableIds.filter(id => id !== item.id); })} />成果：{item.name}</label>))}</div></details></div>)}{!gateRows.length && <p className="text-slate-500">暂无 GA。请在任务页添加。</p>}</div></section>
        {proposal && <section className="bg-orange-50 rounded-2xl border border-orange-200 p-6"><h2 className="font-bold text-lg mb-3">未采纳的排期候选</h2><p className="text-sm">标准预计 {proposal.baselineDate || '未知'} → 候选 {proposal.proposedDate || '未知'}；{proposal.feasible ? '在当前已知约束内可达' : '当前约束下不可达'}</p><ul className="my-3 text-sm space-y-1">{proposal.changes.map(change => <li key={change.entityId}>{allTasks.find(entry => entry.task.id === change.entityId)?.task.title || allDeliverables.find(entry => entry.deliverable.id === change.entityId)?.deliverable.name || change.entityId}：{change.previous} → {change.proposed} 工作日</li>)}</ul>{proposalForecast && <div className="my-3 grid gap-2 sm:grid-cols-2">{workspace.projects.flatMap(owner => owner.gates.map(gate => <p key={gate.id} className="rounded border bg-white p-2 text-sm">{owner.name} / {gate.name}：标准 {forecast?.gates[gate.id]?.date || "无法预测"} → 候选 {proposalForecast.gates[gate.id]?.date || "无法预测"}，目标 {gate.targetDate}{gate.deadlineType === "hard" ? "（硬截止）" : ""}</p>))}</div>}{proposal.reasons.map(reason => <p key={reason} className="text-sm text-orange-800">{reason}</p>)}<div className="mt-4 flex gap-2"><button disabled={!proposal.feasible} className={`${classes.button} disabled:opacity-40`} onClick={adoptProposal}>确认采纳为新版计划</button><button className={classes.secondary} onClick={() => setProposal(null)}>放弃候选</button></div></section>}
        <section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">风险与原因</h2>{forecast?.risks.map(risk => <div key={`${risk.type}:${risk.sourceId}`} className="py-2 border-b text-sm"><strong className="text-orange-700">{risk.type}</strong> · {risk.detail}{remedy(risk.type) && <p className="mt-1 text-slate-600">{remedy(risk.type)}</p>}</div>)}{!forecast?.risks.length && <p className="text-slate-500">当前无计算风险。</p>}</section>
        <section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">风险历史</h2>{workspace.riskEvents.map(event => <div key={event.id} className="py-2 border-b text-sm flex flex-wrap gap-3 items-center"><strong>{event.type}</strong><span>{event.firstDetectedAt.slice(0, 10)} 首次发现</span>{event.initialDelayWorkdays !== undefined && <span>最初晚 {event.initialDelayWorkdays} 工作日</span>}<span>{event.initialSnapshot}</span>{event.handlingNote && <span>处理意见：{event.handlingNote}</span>}{event.resolvedAt && <span>解除于 {event.resolvedAt.slice(0, 10)}</span>}<span className={event.state === 'resolved' ? 'text-green-700' : 'text-orange-700'}>{event.state === 'resolved' ? '已解除' : event.handlingDecision === 'accepted' ? '已接受风险，仍需关注' : event.state === 'mitigated' ? '已有缓解方案' : '待处理'}</span>{event.state === 'open' && <button className="text-blue-700" onClick={() => { const note = window.prompt('接受风险的处理意见'); if (!note?.trim()) return; change(draft => { const item = draft.riskEvents.find(entry => entry.id === event.id)!; item.handlingDecision = 'accepted'; item.handlingNote = note.trim(); }); }}>接受风险</button>}{event.state === "open" && <button className="text-blue-700" onClick={() => { const note = window.prompt("请记录已落实的缓解措施"); if (!note?.trim()) return; change(draft => { const item = draft.riskEvents.find(entry => entry.id === event.id)!; item.state = "mitigated"; item.handlingDecision = "mitigated"; item.handlingNote = note.trim(); }); }}>记录已有缓解措施</button>}</div>)}{!workspace.riskEvents.length && <p className="text-slate-500">暂无历史风险。</p>}</section>
      </>}
      {tab === 'tasks' && <>
        <form onSubmit={addStage} className="bg-white rounded-2xl border border-slate-200 p-4 flex flex-wrap gap-3 items-end"><label className="text-xs font-semibold text-slate-500">新增阶段<input className={classes.input} value={newStage} onChange={event => setNewStage(event.target.value)} placeholder="阶段名称" /></label><button className={classes.button}>添加阶段</button></form>
        <section className="bg-white rounded-2xl border border-slate-200 p-5 flex flex-wrap gap-3 items-end"><form onSubmit={addTask} className="flex gap-2 items-end"><label className="text-xs font-semibold text-slate-500">阶段<select className={classes.input} value={newTaskStage} onChange={event => setNewTaskStage(event.target.value)}><option value="">首个阶段</option>{project.stages.map(stage => <option key={stage.id} value={stage.id}>{stage.name}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">新任务<input className={classes.input} value={newTask} onChange={event => setNewTask(event.target.value)} placeholder="任务名称" /></label><button className={classes.button}><Plus className="inline w-4 h-4" /> 添加</button></form><form onSubmit={addDeliverable} className="flex flex-wrap gap-2 items-end"><label className="text-xs font-semibold text-slate-500">所属任务<select className={classes.input} value={deliverableTask} onChange={event => setDeliverableTask(event.target.value)}><option value="">选择任务</option>{project.tasks.map(task => <option key={task.id} value={task.id}>{task.title}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">新成果<input className={classes.input} value={newDeliverable} onChange={event => setNewDeliverable(event.target.value)} placeholder="成果名称" /></label><select aria-label="成果类别" className={classes.input} value={newDeliverableKind} onChange={event => setNewDeliverableKind(event.target.value as Deliverable['kind'])}><option value="required">必需成果</option><option value="ordinary">普通成果</option></select><button className={classes.secondary}>添加成果</button></form></section>
        {taskToDelete && <section role="dialog" aria-label="确认删除任务" className="rounded-2xl border-2 border-red-300 bg-red-50 p-5 text-sm"><h2 className="font-bold">删除任务「{taskToDelete.title}」</h2><p>该任务有 {taskDeletionImpact(workspace, taskToDelete.id).outgoingCount} 条下游引用、{taskDeletionImpact(workspace, taskToDelete.id).gateCount} 项 GA 完成判据。删除后，下游来源会保留为缺失待修复，GA 判据将移除该任务；实际记录会从当前项目中删除。</p><div className="mt-3 flex gap-2"><button className="rounded-lg bg-red-700 px-4 py-2 text-white" onClick={() => { if (change(draft => Object.assign(draft, deleteTaskPreservingReferences(draft, taskToDelete.id)))) setPendingDeleteTaskId(''); }}>确认删除任务</button><button className={classes.secondary} onClick={() => setPendingDeleteTaskId('')}>取消</button></div></section>}
        {taskToComplete && <section role="dialog" aria-label="确认完成任务" className="rounded-2xl border-2 border-blue-300 bg-blue-50 p-5 text-sm"><h2 className="text-lg font-bold">确认完成：{taskToComplete.title}</h2><p className="mt-2">必须先交付全部必需成果，并处理所有未交付普通成果。实际完成日期由你确认。</p>{taskToComplete.deliverables.filter(item => item.kind === 'required' && item.status !== 'delivered').map(item => <p key={item.id} className="text-red-700">必需成果未交付：{item.name}</p>)}{taskToComplete.deliverables.filter(item => item.kind === 'ordinary' && item.status === 'pending').map(item => <div key={item.id} className="mt-2 flex flex-wrap items-center gap-2 rounded border bg-white p-2"><strong>{item.name}</strong><input aria-label={`${item.name}完成前取消原因`} className="border rounded p-1" placeholder="取消原因" value={completionReasons[item.id] || ''} onChange={event => setCompletionReasons(previous => ({ ...previous, [item.id]: event.target.value }))} /><button className="text-red-700" onClick={() => editDeliverable(item.id, draft => { draft.cancellationReason = completionReasons[item.id]; draft.status = 'cancelled'; })}>取消成果</button><label>或转移到 <select aria-label={`${item.name}完成前转移目标`} className="border rounded p-1" value="" onChange={event => transferDeliverable(item.id, event.target.value)}><option value="">选择任务</option>{allTasks.filter(entry => entry.task.id !== taskToComplete.id).map(entry => <option key={entry.task.id} value={entry.task.id}>{entry.project.name} / {entry.task.title}</option>)}</select></label></div>)}<div className="mt-3 flex flex-wrap gap-3 items-center"><label>实际完成日期 <input aria-label="确认任务实际完成日期" type="date" className="border rounded p-2" value={completionDate} onChange={event => setCompletionDate(event.target.value)} /></label><button className={classes.button} onClick={() => { const saved = editTask(taskToComplete.id, draft => { draft.actualFinishDate = completionDate; draft.status = 'done'; }); if (saved) setCompletionTaskId(''); }}>确认实际完成</button><button className={classes.secondary} onClick={() => setCompletionTaskId('')}>暂不结束</button></div></section>}
        <div className="flex items-center gap-3 text-sm"><label>状态筛选 <select aria-label="任务状态筛选" className="border rounded p-2" value={taskFilter} onChange={event => setTaskFilter(event.target.value as typeof taskFilter)}><option value="all">全部</option><option value="not_started">未开始</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="cancelled">已取消</option></select></label><label className="flex items-center gap-1"><input type="checkbox" checked={riskOnly} onChange={event => setRiskOnly(event.target.checked)} />只看有风险任务</label><span className="text-slate-500">点击阶段标题可折叠</span></div>
        {[...project.stages].sort((a, b) => a.order - b.order).map(stage => <section key={stage.id} className="bg-white rounded-2xl border border-slate-200 overflow-hidden"><div className="bg-slate-50 p-4 flex flex-wrap items-center gap-2"><button aria-label={`${stage.name}折叠或展开`} className="text-blue-700" onClick={() => setCollapsedStages(previous => previous.includes(stage.id) ? previous.filter(id => id !== stage.id) : [...previous, stage.id])}>{collapsedStages.includes(stage.id) ? "展开" : "折叠"}</button><input aria-label={`${stage.name}阶段名称`} className="font-bold bg-transparent border-b border-transparent focus:border-blue-500" value={stage.name} onChange={event => change(draft => { draft.projects.flatMap(item => item.stages).find(item => item.id === stage.id)!.name = event.target.value; })} /><button className="text-xs text-blue-700" onClick={() => moveStage(stage.id, -1)}>上移阶段</button><button className="text-xs text-blue-700" onClick={() => moveStage(stage.id, 1)}>下移阶段</button><button className="text-xs text-red-700" onClick={() => { if (project.stages.length === 1) { setError("至少保留一个阶段"); return; } if (project.tasks.some(task => task.stageId === stage.id) || project.gates.some(gate => gate.stageId === stage.id)) { setError("请先将任务和 GA 移到其他阶段"); return; } if (window.confirm(`删除空阶段「${stage.name}」？`)) change(draft => { draft.projects.find(item => item.id === project.id)!.stages = draft.projects.find(item => item.id === project.id)!.stages.filter(item => item.id !== stage.id); }); }}>删除空阶段</button></div>{!collapsedStages.includes(stage.id) && <div className="overflow-x-auto"><table className="w-full min-w-[1100px] text-sm"><thead className="text-left text-slate-500"><tr><th className="p-3">任务</th><th>标准预测</th><th>标准/最短工作日</th><th>剩余/延期</th><th>状态</th><th>实际开始</th><th>实际完成</th><th>成果</th></tr></thead><tbody>{project.tasks.filter(task => task.stageId === stage.id && (taskFilter === 'all' || task.status === taskFilter) && (!riskOnly || Boolean(forecast?.risks.some(risk => risk.sourceId === task.id || task.deliverables.some(item => item.id === risk.sourceId))))).map(task => <tr key={task.id} className="border-t align-top"><td className="p-3 font-semibold"><input aria-label={`${task.title}任务名称`} className="w-40 border-b border-transparent focus:border-blue-500" value={task.title} onChange={event => editTask(task.id, t => { t.title = event.target.value; })} /><div className="flex gap-2 mt-2 text-xs font-normal"><button className="text-blue-700" onClick={() => moveTask(task.id, -1)}>上移</button><button className="text-blue-700" onClick={() => moveTask(task.id, 1)}>下移</button><button className="text-red-700" onClick={() => setPendingDeleteTaskId(task.id)}>删除</button></div><select aria-label={`${task.title}所属阶段`} className="mt-2 w-44 border rounded p-1 font-normal" value={task.stageId} onChange={event => editTask(task.id, draft => { draft.stageId = event.target.value; })}>{project.stages.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select><textarea aria-label={`${task.title}任务说明`} className="mt-2 w-44 border rounded p-1 font-normal" placeholder="任务说明" value={task.description || ''} onChange={event => editTask(task.id, t => { t.description = event.target.value; })} /><input aria-label={`${task.title}负责人说明`} className="mt-1 w-44 border rounded p-1 font-normal" placeholder="负责人说明" value={task.ownerNote || ''} onChange={event => editTask(task.id, t => { t.ownerNote = event.target.value; })} /><textarea aria-label={`${task.title}备注`} className="mt-1 w-44 border rounded p-1 font-normal" placeholder="延期等备注" value={task.notes || ''} onChange={event => editTask(task.id, t => { t.notes = event.target.value; })} /></td><td className="py-3"><div><span className="text-xs text-slate-500">标准</span> {forecast?.tasks[task.id]?.startDate || '—'} → {forecast?.tasks[task.id]?.finishDate || '—'}</div>{acceptedForecast?.tasks[task.id] && <div className="text-blue-700"><span className="text-xs">已采纳</span> {acceptedForecast.tasks[task.id].startDate} → {acceptedForecast.tasks[task.id].finishDate}</div>}<details className="mt-1"><summary className="cursor-pointer text-xs text-blue-700">日期依据</summary><p className="text-xs text-slate-600">原始预计完成 {workspace.baselineSnapshots?.find(item => item.projectId === project.id)?.taskFinishDates?.[task.id] || "未记录"}</p><ul className="max-w-64 text-xs text-slate-600">{forecast?.tasks[task.id]?.basis.map((basis, index) => <li key={index}>{basis}</li>)}<li>工期 {task.status === 'in_progress' && task.remainingWorkdays ? `剩余 ${task.remainingWorkdays} 工作日` : `${task.standardDurationDays} 工作日`}</li>{workspace.bookings.filter(booking => booking.taskId === task.id).map(booking => <li key={booking.id}>独占资源：{workspace.resources.find(resource => resource.id === booking.resourceId)?.name}</li>)}</ul></details></td><td className="py-3"><input aria-label={`${task.title}标准工期`} type="number" min="1" className="w-16 border rounded p-1" value={task.standardDurationDays} onChange={event => editTask(task.id, t => { t.standardDurationDays = Number(event.target.value); })} /> / <input aria-label={`${task.title}最短工期`} type="number" min="1" className="w-16 border rounded p-1" value={task.minimumDurationDays} onChange={event => editTask(task.id, t => { t.minimumDurationDays = Number(event.target.value); })} /></td><td className="py-3"><input aria-label={`${task.title}剩余工作日`} title="进行中任务使用剩余工作日预测" type="number" min="1" placeholder="剩余" className="w-16 border rounded p-1" value={task.remainingWorkdays ?? ''} onChange={event => editTask(task.id, t => { t.remainingWorkdays = event.target.value ? Number(event.target.value) : undefined; })} /> / <input aria-label={`${task.title}人工延期工作日`} title="未开始任务的人工延期" type="number" min="0" placeholder="延期" className="w-16 border rounded p-1" value={task.manualDelayWorkdays ?? ''} onChange={event => editTask(task.id, t => { t.manualDelayWorkdays = event.target.value ? Number(event.target.value) : undefined; })} /></td><td className="py-3"><select aria-label={`${task.title}状态`} className="border rounded p-1" value={task.status} onChange={event => { if (event.target.value === 'done') { setCompletionTaskId(task.id); setCompletionDate(task.actualFinishDate || dateToday()); } else editTask(task.id, t => { t.status = event.target.value as Task['status']; }); }}><option value="not_started">未开始</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="cancelled">已取消</option></select></td><td className="py-3"><input aria-label={`${task.title}实际开始`} type="date" className="border rounded p-1" value={task.actualStartDate || ''} onChange={event => editTask(task.id, t => { t.actualStartDate = event.target.value || undefined; })} />{task.actualStartDate && !isWorkday(task.actualStartDate) && <p className="text-xs text-orange-700">非工作日实际开始已记录；计划仍按工作日计算</p>}</td><td className="py-3"><input aria-label={`${task.title}实际完成`} type="date" className="border rounded p-1" value={task.actualFinishDate || ''} onChange={event => editTask(task.id, t => { t.actualFinishDate = event.target.value || undefined; })} />{task.actualFinishDate && !isWorkday(task.actualFinishDate) && <p className="text-xs text-orange-700">非工作日实际完成已记录</p>}</td><td className="py-3">{task.deliverables.map(item => <div key={item.id} className="mb-2 rounded bg-slate-50 p-2"><input aria-label={`${item.name}成果名称`} className="w-32 border-b border-transparent focus:border-blue-500 font-semibold" value={item.name} onChange={event => editDeliverable(item.id, d => { d.name = event.target.value; })} /><select aria-label={`${item.name}成果类别`} className="ml-1 border rounded p-1" value={item.kind} onChange={event => editDeliverable(item.id, d => { d.kind = event.target.value as Deliverable['kind']; })}><option value="required">必需</option><option value="ordinary">普通</option></select> <span className="text-slate-500">预计 {forecast?.deliverables[item.id]?.date || '—'}</span><input aria-label={`${item.name}失效原因`} className="ml-2 border rounded p-1" placeholder="失效原因（标记失效前填写）" value={item.invalidationReason || ''} onChange={event => editDeliverable(item.id, d => { d.invalidationReason = event.target.value; })} /><input aria-label={`${item.name}取消原因`} className="ml-2 border rounded p-1" placeholder="取消原因（取消前填写）" value={item.cancellationReason || ''} onChange={event => editDeliverable(item.id, d => { d.cancellationReason = event.target.value; })} /><select aria-label={`${item.name}状态`} className="ml-2 border rounded p-1" value={item.status} onChange={event => setDeliverableStatus(item.id, event.target.value as Deliverable['status'])}><option value="pending">未交付</option><option value="delivered">已交付</option><option value="invalidated">已失效</option><option value="cancelled">已取消</option></select><div className="mt-2 flex flex-wrap gap-2 items-center"><label>标准第 <input aria-label={`${item.name}标准交付工作日`} type="number" min="1" className="w-14 border rounded p-1" value={item.standardOffsetDays} onChange={event => editDeliverable(item.id, d => { d.standardOffsetDays = Number(event.target.value); })} /> 天</label><label>最早第 <input aria-label={`${item.name}最早交付工作日`} type="number" min="1" className="w-14 border rounded p-1" value={item.earliestOffsetDays || ''} onChange={event => editDeliverable(item.id, d => { d.earliestOffsetDays = event.target.value ? Number(event.target.value) : undefined; })} /> 天</label><label>实际交付 <input aria-label={`${item.name}实际交付日期`} type="date" className="border rounded p-1" value={item.actualDeliveredDate || ''} onChange={event => editDeliverable(item.id, d => { d.actualDeliveredDate = event.target.value || undefined; })} /></label><input aria-label={`${item.name}版本说明`} className="border rounded p-1" placeholder="普通版本变更说明" value={versionNotes[item.id] || ''} onChange={event => setVersionNotes(previous => ({ ...previous, [item.id]: event.target.value }))} /><button className="text-blue-700" onClick={() => { const note = versionNotes[item.id]?.trim(); if (!note) { setError('请填写版本变更说明'); return; } editDeliverable(item.id, d => ordinaryVersionUpdate(d, note)); setVersionNotes(previous => ({ ...previous, [item.id]: '' })); }}>记录普通版本</button><span className="text-slate-500">有效版本 {item.versionHistory.find(version => version.id === item.currentVersionId)?.label || '未交付'}</span><details className="w-full"><summary className="text-blue-700 cursor-pointer">版本历史 ({item.versionHistory.length})</summary>{item.versionHistory.map(version => <p key={version.id}>{version.label} · {version.deliveredAt || '未交付'}{version.invalidatedAt ? ' · 已失效' : ''}{version.changeNote ? ` · ${version.changeNote}` : ''}</p>)}</details>{item.kind === 'ordinary' && item.status === 'pending' && <label>转移到 <select aria-label={`${item.name}转移目标`} className="border rounded p-1" value="" onChange={event => transferDeliverable(item.id, event.target.value)}><option value="">选择任务</option>{allTasks.filter(entry => entry.task.id !== task.id).map(entry => <option key={entry.task.id} value={entry.task.id}>{entry.project.name} / {entry.task.title}</option>)}</select></label>}</div></div>)}</td></tr>)}</tbody></table></div>}</section>)}
      </>}
      {tab === 'dependencies' && <section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">跨项目成果依赖</h2><form onSubmit={addDependency} className="flex flex-wrap gap-3 items-end"><label className="text-xs font-semibold text-slate-500">前置成果<select className={classes.input} value={dependencySource} onChange={event => setDependencySource(event.target.value)}><option value="">选择成果</option>{allDeliverables.map(({ deliverable, project: owner }) => <option key={deliverable.id} value={deliverable.id}>{owner.name} / {deliverable.name}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">后续对象<select className={classes.input} value={dependencyTargetType} onChange={event => { setDependencyTargetType(event.target.value as Dependency['targetType']); setDependencyTarget(''); }}><option value="task_start">任务开始</option><option value="deliverable">成果交付</option></select></label><label className="text-xs font-semibold text-slate-500">目标<select className={classes.input} value={dependencyTarget} onChange={event => setDependencyTarget(event.target.value)}><option value="">选择目标</option>{dependencyTargetType === 'task_start' ? allTasks.map(({ task, project: owner }) => <option key={task.id} value={task.id}>{owner.name} / {task.title}</option>) : allDeliverables.map(({ deliverable, project: owner }) => <option key={deliverable.id} value={deliverable.id}>{owner.name} / {deliverable.name}</option>)}</select></label><button className={classes.button}><Workflow className="inline w-4 h-4" /> 建立依赖</button></form><div className="mt-5 space-y-2">{workspace.dependencies.map((dependency: Dependency) => <div key={dependency.id} className="rounded-lg border p-3 text-sm">{allDeliverables.find(item => item.deliverable.id === dependency.sourceId)?.deliverable.name || dependency.sourceNameSnapshot || '任务完成'} → {(dependency.targetType === 'deliverable' ? allDeliverables.find(item => item.deliverable.id === dependency.targetId)?.deliverable.name : allTasks.find(item => item.task.id === dependency.targetId)?.task.title) || '目标缺失'} {allDeliverables.find(item => item.deliverable.id === dependency.sourceId) && <button className="ml-3 text-blue-700" onClick={() => { const sourceProjectId = allDeliverables.find(item => item.deliverable.id === dependency.sourceId)!.project.id; if (change(draft => { draft.currentProjectId = sourceProjectId; })) { setProjectId(sourceProjectId); setTab("tasks"); } }}>查看来源项目</button>} {dependency.sourceType === 'deliverable' && allDeliverables.find(item => item.deliverable.id === dependency.sourceId)?.deliverable.currentVersionId !== dependency.acceptedSourceVersionId && <button className="ml-3 text-blue-700" onClick={() => change(draft => { const edge = draft.dependencies.find(item => item.id === dependency.id)!; const previous = edge.acceptedSourceVersionId; edge.acceptedSourceVersionId = allDeliverables.find(item => item.deliverable.id === edge.sourceId)?.deliverable.currentVersionId; draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: 'dependency', entityId: edge.id, action: 'acceptSourceVersion', previous, next: edge.acceptedSourceVersionId }); })}>接纳当前成果版本</button>}{dependency.sourceType === 'deliverable' && !allDeliverables.some(item => item.deliverable.id === dependency.sourceId) && <select aria-label="重新绑定缺失成果" className="ml-3 border rounded p-1" value="" onChange={event => change(draft => { const edge = draft.dependencies.find(item => item.id === dependency.id)!; const previous = edge.sourceId; edge.sourceId = event.target.value; edge.acceptedSourceVersionId = draft.projects.flatMap(item => item.tasks).flatMap(task => task.deliverables).find(item => item.id === event.target.value)?.currentVersionId; draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: 'dependency', entityId: edge.id, action: 'rebindSource', previous, next: edge.sourceId }); })}><option value="">重新绑定来源</option>{allDeliverables.map(item => <option key={item.deliverable.id} value={item.deliverable.id}>{item.project.name} / {item.deliverable.name}</option>)}</select>}<button className="ml-3 text-red-700" onClick={() => { const reason = window.prompt("移除依赖的原因（留存审计）"); if (!reason?.trim()) return; change(draft => { draft.dependencies = draft.dependencies.filter(item => item.id !== dependency.id); draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: "dependency", entityId: dependency.id, action: "remove", previous: dependency.sourceId + " → " + dependency.targetId, note: reason.trim() }); }); }}>移除</button></div>)}</div><div className="mt-8 border-t pt-5"><h3 className="font-semibold mb-3">成果变更影响处理</h3>{allDeliverables.filter(entry => ['invalidated', 'cancelled'].includes(entry.deliverable.status) && downstreamOf(workspace, entry.deliverable.id).length > 0).map(entry => <div key={entry.deliverable.id} className="mb-4 rounded-lg border border-orange-200 bg-orange-50 p-3 text-sm"><strong>{entry.project.name} / {entry.deliverable.name}</strong> 已{entry.deliverable.status === 'invalidated' ? '失效' : '取消'}；以下下游实际记录保持不变。{downstreamOf(workspace, entry.deliverable.id).map(targetId => { const targetTask = allTasks.find(item => item.task.id === targetId); const targetOutcome = allDeliverables.find(item => item.deliverable.id === targetId); const decision = workspace.impactDecisions?.find(item => item.sourceDeliverableId === entry.deliverable.id && item.targetId === targetId); return <div key={targetId} className="mt-2 flex flex-wrap items-center gap-2"><span>{targetTask ? `${targetTask.project.name} / ${targetTask.task.title}` : targetOutcome ? `${targetOutcome.project.name} / ${targetOutcome.deliverable.name}` : targetId}</span><select aria-label={`${targetId}影响处理`} className="border rounded p-1" value={decision?.decision || 'pending'} onChange={event => change(draft => decideImpact(draft, entry.deliverable.id, targetId, event.target.value as 'unaffected' | 'accept_risk' | 'rework' | 'pending'))}><option value="pending">暂待确认</option><option value="unaffected">不受影响</option><option value="accept_risk">接受风险继续</option><option value="rework">需要返工</option></select></div>; })}</div>)}{!allDeliverables.some(entry => ['invalidated', 'cancelled'].includes(entry.deliverable.status) && downstreamOf(workspace, entry.deliverable.id).length > 0) && <p className="text-sm text-slate-500">暂无需要逐项处理的成果影响。</p>}</div></section>}
      {tab === 'resources' && <section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">独占资源</h2><form className="flex gap-2 mb-4" onSubmit={event => { event.preventDefault(); if (!newResource.trim()) return; change(draft => draft.resources.push({ id: id(), name: newResource.trim(), exclusive: true })); setNewResource(''); }}><input aria-label="新资源名称" className={classes.input} value={newResource} onChange={event => setNewResource(event.target.value)} placeholder="例如：测试设备 A" /><button className={classes.button}>添加资源</button></form><form className="flex flex-wrap gap-2" onSubmit={event => { event.preventDefault(); if (!bookingResource || !bookingTask) return; change(draft => draft.bookings.push({ id: id(), resourceId: bookingResource, taskId: bookingTask, anchor: bookingAnchor, fixedStartDate: bookingAnchor === 'fixed_date' ? bookingDate : undefined, offsetDays: bookingAnchor === 'task_relative' ? bookingOffset : undefined, durationWorkdays: bookingDays })); }}><select aria-label="预约资源" className={classes.input} value={bookingResource} onChange={event => setBookingResource(event.target.value)}><option value="">资源</option>{workspace.resources.map(resource => <option key={resource.id} value={resource.id}>{resource.name}</option>)}</select><select aria-label="预约任务" className={classes.input} value={bookingTask} onChange={event => setBookingTask(event.target.value)}><option value="">任务</option>{allTasks.map(({ task, project: owner }) => <option key={task.id} value={task.id}>{owner.name} / {task.title}</option>)}</select><select aria-label="预约方式" className={classes.input} value={bookingAnchor} onChange={event => setBookingAnchor(event.target.value as 'fixed_date' | 'task_relative')}><option value="fixed_date">锁定日期</option><option value="task_relative">相对任务开始</option></select>{bookingAnchor === 'fixed_date' ? <input aria-label="预约日期" type="date" className={classes.input} value={bookingDate} onChange={event => setBookingDate(event.target.value)} /> : <label className="text-sm">任务开始后第 <input aria-label="预约相对偏移工作日" type="number" min="0" className={`${classes.input} w-24`} value={bookingOffset} onChange={event => setBookingOffset(Number(event.target.value))} /> 个工作日</label>}<input aria-label="预约工作日数" type="number" min="1" className={`${classes.input} w-24`} value={bookingDays} onChange={event => setBookingDays(Number(event.target.value))} /><button className={classes.secondary}>添加预约</button></form><div className="mt-5 space-y-2">{workspace.bookings.map(booking => <div key={booking.id} className="text-sm rounded border p-3 flex flex-wrap items-center gap-2"><strong>{allTasks.find(item => item.task.id === booking.taskId)?.task.title || "任务已删除"}</strong><select aria-label={`${booking.id}预约资源`} disabled={Boolean(booking.actualOccupiedDates?.length)} className="border rounded p-1" value={booking.resourceId} onChange={event => change(draft => { draft.bookings.find(item => item.id === booking.id)!.resourceId = event.target.value; })}>{workspace.resources.map(resource => <option key={resource.id} value={resource.id}>{resource.name}</option>)}</select>{booking.anchor === 'fixed_date' ? <input aria-label={`${booking.id}锁定日期`} disabled={Boolean(booking.actualOccupiedDates?.length)} type="date" className="border rounded p-1" value={booking.fixedStartDate} onChange={event => change(draft => { draft.bookings.find(item => item.id === booking.id)!.fixedStartDate = event.target.value; })} /> : <label>任务开始后 <input aria-label={`${booking.id}相对偏移`} disabled={Boolean(booking.actualOccupiedDates?.length)} type="number" min="0" className="w-16 border rounded p-1" value={booking.offsetDays || 0} onChange={event => change(draft => { draft.bookings.find(item => item.id === booking.id)!.offsetDays = Number(event.target.value); })} /> 工作日</label>}<label>占用 <input aria-label={`${booking.id}占用工作日`} disabled={Boolean(booking.actualOccupiedDates?.length)} type="number" min="1" className="w-16 border rounded p-1" value={booking.durationWorkdays} onChange={event => change(draft => { draft.bookings.find(item => item.id === booking.id)!.durationWorkdays = Number(event.target.value); })} /> 天</label><span className="text-slate-500">实际占用：{booking.actualOccupiedDates?.join('、') || '未登记'}</span><input aria-label="实际占用日期" type="date" className="border rounded p-1" value={occupiedDate} onChange={event => setOccupiedDate(event.target.value)} /><button className="text-blue-700" onClick={() => change(draft => { const item = draft.bookings.find(entry => entry.id === booking.id)!; item.actualOccupiedDates ||= []; if (!item.actualOccupiedDates.includes(occupiedDate)) item.actualOccupiedDates.push(occupiedDate); })}>登记实际占用</button><button className="text-red-700" onClick={() => { if (!window.confirm('删除此预约？已有实际占用记录也会随预约删除。')) return; change(draft => { draft.bookings = draft.bookings.filter(item => item.id !== booking.id); draft.auditTrail ||= []; draft.auditTrail.push({ id: id(), at: new Date().toISOString(), entityType: 'booking', entityId: booking.id, action: 'delete', previous: booking.resourceId + ' / ' + booking.taskId }); }); }}>删除</button></div>)}</div><p className="mt-3 text-xs text-slate-500">资源按完整工作日判重；同日占用视为冲突。</p><div className="mt-3 flex flex-wrap gap-2">{workspace.resources.map(resource => <button key={resource.id} className={classes.button} onClick={() => { const options = proposeResourceAlternatives(workspace, resource.id, dateToday()); setResourceAlternatives(options); if (!options.length) setError(`${resource.name} 当前没有可比较的预约冲突`); }}>{resource.name} · 比较两种执行顺序</button>)}</div>{resourceAlternatives.length > 0 && <div className="mt-4 grid gap-3 md:grid-cols-2">{resourceAlternatives.map(candidate => <div key={candidate.id} className="rounded-lg border border-blue-200 bg-blue-50 p-4 text-sm"><strong>{candidate.title}</strong><p className={candidate.feasible ? "text-green-700" : "text-red-700"}>{candidate.feasible ? "当前约束内可行" : "当前约束内不可行"}</p><ul className="mt-2 space-y-1">{candidate.gateImpacts.map(gate => <li key={gate.gateId}>{workspace.projects.find(project => project.id === gate.projectId)?.name} / {workspace.projects.flatMap(project => project.gates).find(item => item.id === gate.gateId)?.name}：{gate.before || "未知"} → {gate.after || "未知"}，目标 {gate.target}{gate.deadlineType === "hard" ? "（硬截止）" : ""}</li>)}</ul>{candidate.reasons.map(reason => <p key={reason} className="mt-1 text-red-700">{reason}</p>)}<button disabled={!candidate.feasible} className={`${classes.button} mt-3 disabled:opacity-40`} onClick={() => adoptResourceAlternative(candidate)}>确认整体采纳</button></div>)}</div>}<div className="mt-5 rounded-xl border border-orange-200 bg-orange-50 p-4 text-sm"><h3 className="font-semibold">条件性补救模拟</h3><p className="mt-1">先向外部确认资源及可用日期，再在此模拟；未采纳时不会改正式预约。</p><div className="mt-3 flex flex-wrap items-end gap-2"><label>原预约<select aria-label="补救原预约" className={classes.input} value={remedyBooking} onChange={event => setRemedyBooking(event.target.value)}><option value="">选择固定预约</option>{workspace.bookings.filter(booking => booking.anchor === 'fixed_date').map(booking => <option key={booking.id} value={booking.id}>{allTasks.find(entry => entry.task.id === booking.taskId)?.task.title} · {booking.fixedStartDate}</option>)}</select></label><label>确认可用的资源<select aria-label="补救新资源" className={classes.input} value={remedyResource} onChange={event => setRemedyResource(event.target.value)}><option value="">选择资源</option>{workspace.resources.map(resource => <option key={resource.id} value={resource.id}>{resource.name}</option>)}</select></label><label>确认可用日期<input aria-label="补救可用日期" type="date" className={classes.input} value={remedyDate} onChange={event => setRemedyDate(event.target.value)} /></label><button className={classes.secondary} onClick={() => { try { setRemedyProposal(proposeBookingRemedy(workspace, remedyBooking, remedyResource, remedyDate, dateToday())); setError(""); } catch (cause) { setError(cause instanceof Error ? cause.message : "模拟失败"); } }}>重新模拟</button></div>{remedyProposal && <div className="mt-3 rounded-lg border bg-white p-3"><strong>{remedyProposal.title}</strong><p className={remedyProposal.feasible ? "text-green-700" : "text-red-700"}>{remedyProposal.feasible ? "已验证当前本地约束，可提交采纳" : "当前条件不可采纳"}</p>{remedyProposal.gateImpacts.map(gate => <p key={gate.gateId}>{workspace.projects.flatMap(project => project.gates).find(item => item.id === gate.gateId)?.name}：{gate.before || "未知"} → {gate.after || "未知"}，目标 {gate.target}</p>)}{remedyProposal.reasons.map(reason => <p key={reason} className="text-red-700">{reason}</p>)}<button disabled={!remedyProposal.feasible} className={`${classes.button} mt-2 disabled:opacity-40`} onClick={() => { if (commitPlan(remedyProposal.changes, "用户确认外部资源条件")) setRemedyProposal(null); }}>确认采纳</button></div>}</div></section>}
      {tab === 'data' && <div className="grid lg:grid-cols-2 gap-5"><section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">项目管理</h2><div className="mb-4 space-y-1">{workspace.projects.map(item => <button key={item.id} className="block w-full rounded border p-2 text-left text-sm hover:bg-blue-50" onClick={() => { if (change(draft => { draft.currentProjectId = item.id; })) { setProjectId(item.id); setTab("overview"); } }}>{item.name} · {item.status === "archived" ? "已归档" : "进行中"} · {item.tasks.length} 项任务 · {workspace.riskEvents.filter(event => event.state !== "resolved" && (item.gates.some(gate => gate.id === event.sourceId) || item.tasks.some(task => task.id === event.sourceId || task.deliverables.some(deliverable => deliverable.id === event.sourceId)))).length} 项当前风险</button>)}</div><form onSubmit={addProject} className="flex gap-2"><input aria-label="新项目名称" className={classes.input} value={newProject} onChange={event => setNewProject(event.target.value)} placeholder="新项目名称" /><button className={classes.button}><FolderPlus className="inline w-4 h-4" /> 新建</button></form><div className="mt-4 flex flex-wrap gap-2"><button className={classes.secondary} onClick={() => download(`${project.name}-ipd-project.json`, exportProject(workspace, project.id))}>导出当前项目</button><label className={classes.secondary}>导入为新项目<input hidden type="file" accept=".json,application/json" onChange={event => { const file = event.target.files?.[0]; if (file) void importSingleProject(file); event.target.value = ''; }} /></label></div>{pendingProjectImport && <div className="mt-3 rounded-lg border border-blue-200 bg-blue-50 p-3 text-sm"><p>将新增项目「{pendingProjectImport.projects.at(-1)?.name}」。外部成果引用若缺失，会保留为待修复风险。</p><button className={classes.button} onClick={() => { pendingProjectImport.currentProjectId = pendingProjectImport.projects.at(-1)!.id; setWorkspace(pendingProjectImport); setProjectId(pendingProjectImport.currentProjectId); setPendingProjectImport(null); }}>确认导入</button><button className={classes.secondary} onClick={() => setPendingProjectImport(null)}>取消</button></div>}<div className="mt-4 flex flex-wrap gap-2"><label className={classes.secondary}>导入旧版项目 JSON<input hidden type="file" accept=".json,application/json" onChange={event => { const file = event.target.files?.[0]; if (file) void importLegacyFile(file); event.target.value = ""; }} /></label></div>{pendingLegacyImport && <div className="mt-3 rounded-lg border border-blue-200 bg-blue-50 p-3 text-sm"><p>将旧版项目「{pendingLegacyImport.projects.at(-1)?.name}」转换并新增。旧文件没有的成果、版本及实际记录不会补造。</p><button className={classes.button} onClick={() => { pendingLegacyImport.currentProjectId = pendingLegacyImport.projects.at(-1)!.id; setWorkspace(pendingLegacyImport); setProjectId(pendingLegacyImport.currentProjectId); setPendingLegacyImport(null); }}>确认转换</button><button className={classes.secondary} onClick={() => setPendingLegacyImport(null)}>取消</button></div>}<p className="mt-4 text-sm text-slate-500">归档不会删除跨项目依赖。</p><button className="mt-3 text-sm text-red-700" onClick={() => setPendingDeleteProject(true)}>删除当前项目</button>{pendingDeleteProject && <div className="mt-3 rounded-lg border border-red-300 bg-red-50 p-3 text-sm"><p>删除「{project.name}」将移除其 {project.tasks.length} 项任务；其他项目对它的 {deletionImpact.outgoingCount} 条引用会保留为“来源缺失”。受影响项目：{deletionImpact.targetProjectIds.map(projectId => workspace.projects.find(item => item.id === projectId)?.name).join('、') || '无'}。</p><div className="mt-3 flex gap-2"><button className="rounded-lg bg-red-700 px-4 py-2 text-white" onClick={() => { const next = deleteProjectPreservingReferences(workspace, project.id); const issues = validateWorkspace(next); if (issues.length) { setError(issues[0]); return; } next.riskEvents = reconcileRiskHistory(next.riskEvents, forecastWorkspace(next, { today: dateToday() })); setWorkspace(next); setProjectId(next.currentProjectId || next.projects[0]?.id || ''); setPendingDeleteProject(false); setTab('overview'); }}>确认删除</button><button className={classes.secondary} onClick={() => setPendingDeleteProject(false)}>取消</button></div></div>}</section><section className="bg-white rounded-2xl border border-slate-200 p-6"><h2 className="font-bold text-lg mb-4">工作区备份</h2><div className="flex flex-wrap gap-2"><button className={classes.button} onClick={() => download('ipd-workspace.json', makeWorkspaceBackup(workspace))}><Download className="inline w-4 h-4" /> 导出完整工作区</button><label className={classes.secondary}><FileJson className="inline w-4 h-4" /> 导入完整工作区<input hidden type="file" accept=".json,application/json" onChange={event => { const file = event.target.files?.[0]; if (file) void importWorkspace(file); event.target.value = ''; }} /></label></div><p className="mt-4 text-sm text-slate-500">导入会替换当前工作区，请先导出备份。</p>{pendingImport && <div className="mt-4 rounded-lg border border-orange-300 bg-orange-50 p-4 text-sm"><p>待导入 {pendingImport.projects.length} 个项目。确认后将替换当前全部项目和风险历史。</p><div className="mt-3 flex gap-2"><button className={classes.button} onClick={() => { setWorkspace(pendingImport); setProjectId(pendingImport.currentProjectId || pendingImport.projects[0]?.id || ''); setPendingImport(null); }}>确认替换</button><button className={classes.secondary} onClick={() => setPendingImport(null)}>取消</button></div></div>}</section><section className="bg-white rounded-2xl border border-slate-200 p-6 lg:col-span-2"><h2 className="font-bold text-lg mb-3">变更与计划历史</h2><p className="text-xs text-slate-500 mb-3">实际日期、GA 目标、状态与成果转移的修改记录保存在工作区备份中。</p><details><summary className="cursor-pointer text-blue-700">查看 {workspace.auditTrail?.length || 0} 条变更记录</summary><div className="max-h-80 overflow-y-auto mt-3">{[...(workspace.auditTrail || [])].reverse().map(entry => <p key={entry.id} className="border-b py-2 text-sm">{entry.at.slice(0, 19).replace("T", " ")} · {entry.entityType} {entry.entityId} · {entry.action}：{entry.previous || "—"} → {entry.next || "—"}{entry.note ? ` · ${entry.note}` : ""}</p>)}</div></details><details className="mt-3"><summary className="cursor-pointer text-blue-700">查看 {workspace.planRevisions.length} 个已采纳计划版本</summary><div className="max-h-80 overflow-y-auto mt-3">{workspace.planRevisions.map(revision => <p key={revision.id} className="border-b py-2 text-sm">{revision.createdAt.slice(0, 19).replace("T", " ")} · {revision.note || "计划调整"} · 涉及 {revision.affectedProjectIds.length} 个项目、{revision.changes.length} 项变更</p>)}</div></details><p className="mt-4 text-sm text-slate-500">AI 建议为可选增强，尚未启用；所有本地排期和备份功能可离线使用。请勿在浏览器中保存 API 密钥。</p></section></div>}
    </main>
  </div>;
}
